00047 void applyPROFCore(Pel *dst, int dstStride, const Pel *src, int srcStride, int width, int height, const Pel *gradX,
00048                    const Pel *gradY, int gradStride, const int *dMvX, const int *dMvY, int dMvStride, const bool &bi, int shiftNum,
00049                    Pel offset, const ClpRng &clpRng) {
00050   int idx = 0;
00051 
00052   const int dILimit = 1 << std::max<int>(clpRng.bd + 1, 13);
00053   for (int h = 0; h < height; h++)
00054   {
00055     for (int w = 0; w < width; w++)
00056     {
00057       int32_t dI = dMvX[idx] * gradX[w] + dMvY[idx] * gradY[w];
00058       dI = Clip3(-dILimit, dILimit - 1, dI);
00059       dst[w] = src[w] + dI;
00060       if (!bi)
00061       {
00062         dst[w] = (dst[w] + offset) >> shiftNum;
00063         dst[w] = ClipPel(dst[w], clpRng);
00064       }
00065 
00066       idx++;
00067     }
00068     gradX += gradStride;
00069     gradY += gradStride;
00070     dst += dstStride;
00071     src += srcStride;
00072   }
00073 }
