00076 template< typename T >
00077 void addAvgCore( const T* src1, int src1Stride, const T* src2, int src2Stride, T* dest, int dstStride, int width, int height, int rshift, int offset, const ClpRng& clpRng )
00078 {
00079 #define ADD_AVG_CORE_OP( ADDR ) dest[ADDR] = ClipPel( rightShift( ( src1[ADDR] + src2[ADDR] + offset ), rshift ), clpRng )
00080 #define ADD_AVG_CORE_INC    \
00081   src1 += src1Stride;       \
00082   src2 += src2Stride;       \
00083   dest +=  dstStride;       \
00084 
00085   SIZE_AWARE_PER_EL_OP( ADD_AVG_CORE_OP, ADD_AVG_CORE_INC );
00086 
00087 #undef ADD_AVG_CORE_OP
00088 #undef ADD_AVG_CORE_INC
00089 }
00090 
00091 void addBIOAvgCore(const Pel* src0, int src0Stride, const Pel* src1, int src1Stride, Pel *dst, int dstStride, const Pel *gradX0, const Pel *gradX1, const Pel *gradY0, const Pel*gradY1, int gradStride, int width, int height, int tmpx, int tmpy, int shift, int offset, const ClpRng& clpRng)
00092 {
00093   int b = 0;
00094 
00095   for (int y = 0; y < height; y++)
00096   {
00097     for (int x = 0; x < width; x += 4)
00098     {
00099       b = tmpx * (gradX0[x] - gradX1[x]) + tmpy * (gradY0[x] - gradY1[x]);
00100       dst[x] = ClipPel(rightShift((src0[x] + src1[x] + b + offset), shift), clpRng);
00101 
00102       b = tmpx * (gradX0[x + 1] - gradX1[x + 1]) + tmpy * (gradY0[x + 1] - gradY1[x + 1]);
00103       dst[x + 1] = ClipPel(rightShift((src0[x + 1] + src1[x + 1] + b + offset), shift), clpRng);
00104 
00105       b = tmpx * (gradX0[x + 2] - gradX1[x + 2]) + tmpy * (gradY0[x + 2] - gradY1[x + 2]);
00106       dst[x + 2] = ClipPel(rightShift((src0[x + 2] + src1[x + 2] + b + offset), shift), clpRng);
00107 
00108       b = tmpx * (gradX0[x + 3] - gradX1[x + 3]) + tmpy * (gradY0[x + 3] - gradY1[x + 3]);
00109       dst[x + 3] = ClipPel(rightShift((src0[x + 3] + src1[x + 3] + b + offset), shift), clpRng);
00110     }
00111     dst += dstStride;       src0 += src0Stride;     src1 += src1Stride;
00112     gradX0 += gradStride; gradX1 += gradStride; gradY0 += gradStride; gradY1 += gradStride;
00113   }
00114 }
