00116 template<bool PAD = true>
00117 void gradFilterCore(Pel* pSrc, int srcStride, int width, int height, int gradStride, Pel* gradX, Pel* gradY, const int bitDepth)
00118 {
00119   Pel* srcTmp = pSrc + srcStride + 1;
00120   Pel* gradXTmp = gradX + gradStride + 1;
00121   Pel* gradYTmp = gradY + gradStride + 1;
00122   int  shift1 = 6;
00123 
00124   for (int y = 0; y < (height - 2 * BIO_EXTEND_SIZE); y++)
00125   {
00126     for (int x = 0; x < (width - 2 * BIO_EXTEND_SIZE); x++)
00127     {
00128       gradYTmp[x] = ( srcTmp[x + srcStride] >> shift1 ) - ( srcTmp[x - srcStride] >> shift1 );
00129       gradXTmp[x] = ( srcTmp[x + 1] >> shift1 ) - ( srcTmp[x - 1] >> shift1 );
00130     }
00131     gradXTmp += gradStride;
00132     gradYTmp += gradStride;
00133     srcTmp += srcStride;
00134   }
00135 
00136   if (PAD)
00137   {
00138   gradXTmp = gradX + gradStride + 1;
00139   gradYTmp = gradY + gradStride + 1;
00140   for (int y = 0; y < (height - 2 * BIO_EXTEND_SIZE); y++)
00141   {
00142     gradXTmp[-1] = gradXTmp[0];
00143     gradXTmp[width - 2 * BIO_EXTEND_SIZE] = gradXTmp[width - 2 * BIO_EXTEND_SIZE - 1];
00144     gradXTmp += gradStride;
00145 
00146     gradYTmp[-1] = gradYTmp[0];
00147     gradYTmp[width - 2 * BIO_EXTEND_SIZE] = gradYTmp[width - 2 * BIO_EXTEND_SIZE - 1];
00148     gradYTmp += gradStride;
00149   }
00150 
00151   gradXTmp = gradX + gradStride;
00152   gradYTmp = gradY + gradStride;
00153   ::memcpy(gradXTmp - gradStride, gradXTmp, sizeof(Pel)*(width));
00154   ::memcpy(gradXTmp + (height - 2 * BIO_EXTEND_SIZE)*gradStride, gradXTmp + (height - 2 * BIO_EXTEND_SIZE - 1)*gradStride, sizeof(Pel)*(width));
00155   ::memcpy(gradYTmp - gradStride, gradYTmp, sizeof(Pel)*(width));
00156   ::memcpy(gradYTmp + (height - 2 * BIO_EXTEND_SIZE)*gradStride, gradYTmp + (height - 2 * BIO_EXTEND_SIZE - 1)*gradStride, sizeof(Pel)*(width));
00157   }
00158 }
