00160 void calcBIOSumsCore(const Pel* srcY0Tmp, const Pel* srcY1Tmp, Pel* gradX0, Pel* gradX1, Pel* gradY0, Pel* gradY1, int xu, int yu, const int src0Stride, const int src1Stride, const int widthG, const int bitDepth, int* sumAbsGX, int* sumAbsGY, int* sumDIX, int* sumDIY, int* sumSignGY_GX)
00161 {
00162   int shift4 = 4;
00163   int shift5 = 1;
00164 
00165   for (int y = 0; y < 6; y++)
00166   {
00167     for (int x = 0; x < 6; x++)
00168     {
00169       int tmpGX = (gradX0[x] + gradX1[x]) >> shift5;
00170       int tmpGY = (gradY0[x] + gradY1[x]) >> shift5;
00171       int tmpDI = (int)((srcY1Tmp[x] >> shift4) - (srcY0Tmp[x] >> shift4));
00172       *sumAbsGX += (tmpGX < 0 ? -tmpGX : tmpGX);
00173       *sumAbsGY += (tmpGY < 0 ? -tmpGY : tmpGY);
00174       *sumDIX += (tmpGX < 0 ? -tmpDI : (tmpGX == 0 ? 0 : tmpDI));
00175       *sumDIY += (tmpGY < 0 ? -tmpDI : (tmpGY == 0 ? 0 : tmpDI));
00176       *sumSignGY_GX += (tmpGY < 0 ? -tmpGX : (tmpGY == 0 ? 0 : tmpGX));
00177 
00178     }
00179     srcY1Tmp += src1Stride;
00180     srcY0Tmp += src0Stride;
00181     gradX0 += widthG;
00182     gradX1 += widthG;
00183     gradY0 += widthG;
00184     gradY1 += widthG;
00185   }
00186 }
