00189 void calcBlkGradientCore(int sx, int sy, int     *arraysGx2, int     *arraysGxGy, int     *arraysGxdI, int     *arraysGy2, int     *arraysGydI, int     &sGx2, int     &sGy2, int     &sGxGy, int     &sGxdI, int     &sGydI, int width, int height, int unitSize)
00190 {
00191   int     *Gx2 = arraysGx2;
00192   int     *Gy2 = arraysGy2;
00193   int     *GxGy = arraysGxGy;
00194   int     *GxdI = arraysGxdI;
00195   int     *GydI = arraysGydI;
00196 
00197   // set to the above row due to JVET_K0485_BIO_EXTEND_SIZE
00198   Gx2 -= (BIO_EXTEND_SIZE*width);
00199   Gy2 -= (BIO_EXTEND_SIZE*width);
00200   GxGy -= (BIO_EXTEND_SIZE*width);
00201   GxdI -= (BIO_EXTEND_SIZE*width);
00202   GydI -= (BIO_EXTEND_SIZE*width);
00203 
00204   for (int y = -BIO_EXTEND_SIZE; y < unitSize + BIO_EXTEND_SIZE; y++)
00205   {
00206     for (int x = -BIO_EXTEND_SIZE; x < unitSize + BIO_EXTEND_SIZE; x++)
00207     {
00208       sGx2 += Gx2[x];
00209       sGy2 += Gy2[x];
00210       sGxGy += GxGy[x];
00211       sGxdI += GxdI[x];
00212       sGydI += GydI[x];
00213     }
00214     Gx2 += width;
00215     Gy2 += width;
00216     GxGy += width;
00217     GxdI += width;
00218     GydI += width;
00219   }
00220 }
