00222 #if ENABLE_SIMD_OPT_BCW
00223 void removeWeightHighFreq(int16_t* dst, int dstStride, const int16_t* src, int srcStride, int width, int height, int shift, int bcwWeight)
00224 {
00225   int normalizer = ((1 << 16) + (bcwWeight > 0 ? (bcwWeight >> 1) : -(bcwWeight >> 1))) / bcwWeight;
00226   int weight0 = normalizer << g_BcwLog2WeightBase;
00227   int weight1 = (g_BcwWeightBase - bcwWeight)*normalizer;
00228 #define REM_HF_INC  \
00229   src += srcStride; \
00230   dst += dstStride; \
00231 
00232 #define REM_HF_OP( ADDR )      dst[ADDR] =             (dst[ADDR]*weight0 - src[ADDR]*weight1 + (1<<15))>>16
00233 
00234   SIZE_AWARE_PER_EL_OP(REM_HF_OP, REM_HF_INC);
00235 
00236 #undef REM_HF_INC
00237 #undef REM_HF_OP
00238 #undef REM_HF_OP_CLIP
00239 }
00240 
00241 void removeHighFreq(int16_t* dst, int dstStride, const int16_t* src, int srcStride, int width, int height)
00242 {
00243 #define REM_HF_INC  \
00244   src += srcStride; \
00245   dst += dstStride; \
00246 
00247 #define REM_HF_OP( ADDR )      dst[ADDR] =             2 * dst[ADDR] - src[ADDR]
00248 
00249   SIZE_AWARE_PER_EL_OP(REM_HF_OP, REM_HF_INC);
00250 
00251 #undef REM_HF_INC
00252 #undef REM_HF_OP
00253 #undef REM_HF_OP_CLIP
00254 }
00255 #endif
