00257 template<typename T>
00258 void reconstructCore( const T* src1, int src1Stride, const T* src2, int src2Stride, T* dest, int dstStride, int width, int height, const ClpRng& clpRng )
00259 {
00260 #define RECO_CORE_OP( ADDR ) dest[ADDR] = ClipPel( src1[ADDR] + src2[ADDR], clpRng )
00261 #define RECO_CORE_INC     \
00262   src1 += src1Stride;     \
00263   src2 += src2Stride;     \
00264   dest +=  dstStride;     \
00265 
00266   SIZE_AWARE_PER_EL_OP( RECO_CORE_OP, RECO_CORE_INC );
