00273 template<typename T>
00274 void linTfCore( const T* src, int srcStride, Pel *dst, int dstStride, int width, int height, int scale, int shift, int offset, const ClpRng& clpRng, bool bClip )
00275 {
00276 #define LINTF_CORE_OP( ADDR ) dst[ADDR] = ( Pel ) bClip ? ClipPel( rightShift( scale * src[ADDR], shift ) + offset, clpRng ) : ( rightShift( scale * src[ADDR], shift ) + offset )
00277 #define LINTF_CORE_INC  \
00278   src += srcStride;     \
00279   dst += dstStride;     \
00280 
00281   SIZE_AWARE_PER_EL_OP( LINTF_CORE_OP, LINTF_CORE_INC );
00282 
00283 #undef LINTF_CORE_OP
00284 #undef LINTF_CORE_INC
