00318 void copyBufferCore(Pel *src, int srcStride, Pel *dst, int dstStride, int width, int height)
00319 {
00320   int numBytes = width * sizeof(Pel);
00321   for (int i = 0; i < height; i++)
00322   {
00323     memcpy(dst + i * dstStride, src + i * srcStride, numBytes);
00324   }
00325 }
00326 
00327 void paddingCore(Pel *ptr, int stride, int width, int height, int padSize)
00328 {
00329   /*left and right padding*/
00330   Pel *ptrTemp1 = ptr;
00331   Pel *ptrTemp2 = ptr + (width - 1);
00332   int offset = 0;
00333   for (int i = 0; i < height; i++)
00334   {
00335     offset = stride * i;
00336     for (int j = 1; j <= padSize; j++)
00337     {
00338       *(ptrTemp1 - j + offset) = *(ptrTemp1 + offset);
00339       *(ptrTemp2 + j + offset) = *(ptrTemp2 + offset);
00340     }
00341   }
00342   /*Top and Bottom padding*/
00343   int numBytes = (width + padSize + padSize) * sizeof(Pel);
00344   ptrTemp1 = (ptr - padSize);
00345   ptrTemp2 = (ptr + (stride * (height - 1)) - padSize);
00346   for (int i = 1; i <= padSize; i++)
00347   {
00348     memcpy(ptrTemp1 - (i * stride), (ptrTemp1), numBytes);
00349     memcpy(ptrTemp2 + (i * stride), (ptrTemp2), numBytes);
00350   }
00351 }
00352 template<>
00353 void AreaBuf<Pel>::addWeightedAvg(const AreaBuf<const Pel> &other1, const AreaBuf<const Pel> &other2, const ClpRng& clpRng, const int8_t bcwIdx)
00354 {
00355   const int8_t w0 = getBcwWeight(bcwIdx, REF_PIC_LIST_0);
00356   const int8_t w1 = getBcwWeight(bcwIdx, REF_PIC_LIST_1);
00357   const int8_t log2WeightBase = g_BcwLog2WeightBase;
00358 
00359   const Pel* src0 = other1.buf;
00360   const Pel* src2 = other2.buf;
00361   Pel* dest = buf;
00362 
00363   const unsigned src1Stride = other1.stride;
00364   const unsigned src2Stride = other2.stride;
00365   const unsigned destStride = stride;
00366   const int clipbd = clpRng.bd;
00367   const int shiftNum = IF_INTERNAL_FRAC_BITS(clipbd) + log2WeightBase;
00368   const int offset = (1 << (shiftNum - 1)) + (IF_INTERNAL_OFFS << log2WeightBase);
00369 
00370 #define ADD_AVG_OP( ADDR ) dest[ADDR] = ClipPel( rightShift( ( src0[ADDR]*w0 + src2[ADDR]*w1 + offset ), shiftNum ), clpRng )
00371 #define ADD_AVG_INC     \
00372     src0 += src1Stride; \
00373     src2 += src2Stride; \
00374     dest += destStride; \
00375 
00376   SIZE_AWARE_PER_EL_OP(ADD_AVG_OP, ADD_AVG_INC);
00377 
00378 #undef ADD_AVG_OP
00379 #undef ADD_AVG_INC
00380 }
