00382 template<>
00383 void AreaBuf<Pel>::rspSignal(std::vector<Pel>& pLUT)
00384 {
00385   Pel* dst = buf;
00386   Pel* src = buf;
00387     for (unsigned y = 0; y < height; y++)
00388     {
00389       for (unsigned x = 0; x < width; x++)
00390       {
00391         dst[x] = pLUT[src[x]];
00392       }
00393       dst += stride;
00394       src += stride;
00395     }
