00398 template<>
00399 void AreaBuf<Pel>::scaleSignal(const int scale, const bool dir, const ClpRng& clpRng)
00400 {
00401   Pel* dst = buf;
00402   Pel* src = buf;
00403   int sign, absval;
00404   int maxAbsclipBD = (1<<clpRng.bd) - 1;
00405 
00406   if (dir) // forward
00407   {
00408     if (width == 1)
00409     {
00410       THROW("Blocks of width = 1 not supported");
00411     }
00412     else
00413     {
00414       for (unsigned y = 0; y < height; y++)
00415       {
00416         for (unsigned x = 0; x < width; x++)
00417         {
00418           sign = src[x] >= 0 ? 1 : -1;
00419           absval = sign * src[x];
00420           dst[x] = (Pel)Clip3(-maxAbsclipBD, maxAbsclipBD, sign * (((absval << CSCALE_FP_PREC) + (scale >> 1)) / scale));
00421         }
00422         dst += stride;
00423         src += stride;
00424       }
00425     }
00426   }
00427   else // inverse
00428   {
00429     for (unsigned y = 0; y < height; y++)
00430     {
00431       for (unsigned x = 0; x < width; x++)
00432       {
00433         src[x] = (Pel)Clip3((Pel)(-maxAbsclipBD - 1), (Pel)maxAbsclipBD, src[x]);
00434         sign = src[x] >= 0 ? 1 : -1;
00435         absval = sign * src[x];
00436         int val = sign * ((absval * scale + (1 << (CSCALE_FP_PREC - 1))) >> CSCALE_FP_PREC);
00437         if (sizeof(Pel) == 2) // avoid overflow when storing data
00438         {
00439            val = Clip3<int>(-32768, 32767, val);
00440         }
00441         dst[x] = (Pel)val;
00442       }
00443       dst += stride;
00444       src += stride;
00445     }
00446   }
00447 }
00448 
00449 template<>
00450 void AreaBuf<Pel>::addAvg( const AreaBuf<const Pel> &other1, const AreaBuf<const Pel> &other2, const ClpRng& clpRng)
00451 {
00452   const Pel* src0 = other1.buf;
00453   const Pel* src2 = other2.buf;
00454         Pel* dest =        buf;
00455 
00456   const unsigned src1Stride = other1.stride;
00457   const unsigned src2Stride = other2.stride;
00458   const unsigned destStride =        stride;
00459   const int     clipbd      = clpRng.bd;
00460   const int shiftNum = IF_INTERNAL_FRAC_BITS(clipbd) + 1;
00461   const int     offset      = (1 << (shiftNum - 1)) + 2 * IF_INTERNAL_OFFS;
00462 
00463 #if ENABLE_SIMD_OPT_BUFFER && defined(TARGET_SIMD_X86)
00464   if( ( width & 7 ) == 0 )
00465   {
00466     g_pelBufOP.addAvg8( src0, src1Stride, src2, src2Stride, dest, destStride, width, height, shiftNum, offset, clpRng );
00467   }
00468   else if( ( width & 3 ) == 0 )
00469   {
00470     g_pelBufOP.addAvg4( src0, src1Stride, src2, src2Stride, dest, destStride, width, height, shiftNum, offset, clpRng );
00471   }
00472   else
00473 #endif
00474   {
00475 #define ADD_AVG_OP( ADDR ) dest[ADDR] = ClipPel( rightShift( ( src0[ADDR] + src2[ADDR] + offset ), shiftNum ), clpRng )
00476 #define ADD_AVG_INC     \
00477     src0 += src1Stride; \
00478     src2 += src2Stride; \
00479     dest += destStride; \
00480 
00481     SIZE_AWARE_PER_EL_OP( ADD_AVG_OP, ADD_AVG_INC );
00482 
00483 #undef ADD_AVG_OP
00484 #undef ADD_AVG_INC
00485   }
00486 }
00487 
00488 template<>
00489 void AreaBuf<Pel>::toLast( const ClpRng& clpRng )
00490 {
00491         Pel* src       = buf;
00492   const uint32_t srcStride = stride;
00493 
00494   const int  clipbd    = clpRng.bd;
00495   const int shiftNum = IF_INTERNAL_FRAC_BITS(clipbd);
00496   const int  offset    = ( 1 << ( shiftNum - 1 ) ) + IF_INTERNAL_OFFS;
00497 
00498   if (width == 1)
00499   {
00500     THROW( "Blocks of width = 1 not supported" );
00501   }
00502   else if (width&2)
00503   {
00504     for ( int y = 0; y < height; y++ )
00505     {
00506       for (int x=0 ; x < width; x+=2 )
00507       {
00508         src[x + 0] = ClipPel( rightShift( ( src[x + 0] + offset ), shiftNum ), clpRng );
00509         src[x + 1] = ClipPel( rightShift( ( src[x + 1] + offset ), shiftNum ), clpRng );
00510       }
00511       src += srcStride;
00512     }
00513   }
00514   else
00515   {
00516     for ( int y = 0; y < height; y++ )
00517     {
00518       for (int x=0 ; x < width; x+=4 )
00519       {
00520         src[x + 0] = ClipPel( rightShift( ( src[x + 0] + offset ), shiftNum ), clpRng );
00521         src[x + 1] = ClipPel( rightShift( ( src[x + 1] + offset ), shiftNum ), clpRng );
00522         src[x + 2] = ClipPel( rightShift( ( src[x + 2] + offset ), shiftNum ), clpRng );
00523         src[x + 3] = ClipPel( rightShift( ( src[x + 3] + offset ), shiftNum ), clpRng );
00524 
00525       }
00526       src += srcStride;
00527     }
00528   }
00529 }
00530 
00531 
00532 template<>
00533 void AreaBuf<Pel>::copyClip( const AreaBuf<const Pel> &src, const ClpRng& clpRng )
00534 {
00535   const Pel* srcp = src.buf;
00536         Pel* dest =     buf;
00537 
00538   const unsigned srcStride  = src.stride;
00539   const unsigned destStride = stride;
00540 
00541   if( width == 1 )
00542   {
00543     THROW( "Blocks of width = 1 not supported" );
00544   }
00545   else
00546   {
00547 #define RECO_OP( ADDR ) dest[ADDR] = ClipPel( srcp[ADDR], clpRng )
00548 #define RECO_INC        \
00549     srcp += srcStride;  \
00550     dest += destStride; \
00551 
00552     SIZE_AWARE_PER_EL_OP( RECO_OP, RECO_INC );
00553 
00554 #undef RECO_OP
00555 #undef RECO_INC
00556   }
00557 }
00558 
00559 template<>
00560 void AreaBuf<Pel>::roundToOutputBitdepth( const AreaBuf<const Pel> &src, const ClpRng& clpRng )
00561 {
00562   const Pel* srcp = src.buf;
00563         Pel* dest =     buf;
00564   const unsigned srcStride  = src.stride;
00565   const unsigned destStride = stride;
00566 
00567   const int32_t clipbd            = clpRng.bd;
00568   const int32_t shiftDefault      = IF_INTERNAL_FRAC_BITS(clipbd);
00569   const int32_t offsetDefault     = (1<<(shiftDefault-1)) + IF_INTERNAL_OFFS;
00570 
00571   if( width == 1 )
00572   {
00573     THROW( "Blocks of width = 1 not supported" );
00574   }
00575   else
00576   {
00577 #define RND_OP( ADDR ) dest[ADDR] = ClipPel( rightShift( srcp[ADDR] + offsetDefault, shiftDefault), clpRng )
00578 #define RND_INC        \
00579     srcp += srcStride;  \
00580     dest += destStride; \
00581 
00582     SIZE_AWARE_PER_EL_OP( RND_OP, RND_INC );
00583 
00584 #undef RND_OP
00585 #undef RND_INC
00586   }
00587 }
00588 
00589 
00590 template<>
00591 void AreaBuf<Pel>::reconstruct( const AreaBuf<const Pel> &pred, const AreaBuf<const Pel> &resi, const ClpRng& clpRng )
00592 {
00593   const Pel* src1 = pred.buf;
00594   const Pel* src2 = resi.buf;
00595         Pel* dest =      buf;
00596 
00597   const unsigned src1Stride = pred.stride;
00598   const unsigned src2Stride = resi.stride;
00599   const unsigned destStride =      stride;
00600 
00601 #if ENABLE_SIMD_OPT_BUFFER && defined(TARGET_SIMD_X86)
00602   if( ( width & 7 ) == 0 )
00603   {
00604     g_pelBufOP.reco8( src1, src1Stride, src2, src2Stride, dest, destStride, width, height, clpRng );
00605   }
00606   else if( ( width & 3 ) == 0 )
00607   {
00608     g_pelBufOP.reco4( src1, src1Stride, src2, src2Stride, dest, destStride, width, height, clpRng );
00609   }
00610   else
00611 #endif
00612   {
00613 #define RECO_OP( ADDR ) dest[ADDR] = ClipPel( src1[ADDR] + src2[ADDR], clpRng )
00614 #define RECO_INC        \
00615     src1 += src1Stride; \
00616     src2 += src2Stride; \
00617     dest += destStride; \
00618 
00619     SIZE_AWARE_PER_EL_OP( RECO_OP, RECO_INC );
00620 
00621 #undef RECO_OP
00622 #undef RECO_INC
00623   }
00624 }
00625 
00626 template<>
00627 void AreaBuf<Pel>::linearTransform( const int scale, const int shift, const int offset, bool bClip, const ClpRng& clpRng )
00628 {
00629   const Pel* src = buf;
00630         Pel* dst = buf;
00631 
00632   if( width == 1 )
00633   {
00634     THROW( "Blocks of width = 1 not supported" );
00635   }
00636 #if ENABLE_SIMD_OPT_BUFFER && defined(TARGET_SIMD_X86)
00637   else if( ( width & 7 ) == 0 )
00638   {
00639     g_pelBufOP.linTf8( src, stride, dst, stride, width, height, scale, shift, offset, clpRng, bClip );
00640   }
00641   else if( ( width & 3 ) == 0 )
00642   {
00643     g_pelBufOP.linTf4( src, stride, dst, stride, width, height, scale, shift, offset, clpRng, bClip );
00644   }
00645 #endif
00646   else
00647   {
00648 #define LINTF_OP( ADDR ) dst[ADDR] = ( Pel ) bClip ? ClipPel( rightShift( scale * src[ADDR], shift ) + offset, clpRng ) : ( rightShift( scale * src[ADDR], shift ) + offset )
00649 #define LINTF_INC        \
00650     src += stride;       \
00651     dst += stride;       \
00652 
00653     SIZE_AWARE_PER_EL_OP( LINTF_OP, LINTF_INC );
00654 
00655 #undef RECO_OP
00656 #undef RECO_INC
00657   }
00658 }
00659 
00660 #if ENABLE_SIMD_OPT_BUFFER && defined(TARGET_SIMD_X86)
00661 template<>
00662 void AreaBuf<Pel>::subtract( const Pel val )
00663 {
00664   ClpRng clpRngDummy;
00665   linearTransform( 1, 0, -val, false, clpRngDummy );
00666 }
00667 #endif
