00687 
00688 void PelStorage::create( const ChromaFormat &_chromaFormat, const Area& _area, const unsigned _maxCUSize, const unsigned _margin, const unsigned _alignment, const bool _scaleChromaMargin )
00689 {
00690   CHECK( !bufs.empty(), "Trying to re-create an already initialized buffer" );
00691 
00692   chromaFormat = _chromaFormat;
00693 
00694   const uint32_t numCh = getNumberValidComponents( _chromaFormat );
00695 
00696   unsigned extHeight = _area.height;
00697   unsigned extWidth  = _area.width;
00698 
00699   if( _maxCUSize )
00700   {
00701     extHeight = ( ( _area.height + _maxCUSize - 1 ) / _maxCUSize ) * _maxCUSize;
00702     extWidth  = ( ( _area.width  + _maxCUSize - 1 ) / _maxCUSize ) * _maxCUSize;
00703   }
00704 
00705   for( uint32_t i = 0; i < numCh; i++ )
00706   {
00707     const ComponentID compID = ComponentID( i );
00708     const unsigned scaleX = vtm::getComponentScaleX( compID, _chromaFormat );
00709     const unsigned scaleY = vtm::getComponentScaleY( compID, _chromaFormat );
00710 
00711     unsigned scaledHeight = extHeight >> scaleY;
00712     unsigned scaledWidth  = extWidth  >> scaleX;
00713     unsigned ymargin      = _margin >> (_scaleChromaMargin?scaleY:0);
00714     unsigned xmargin      = _margin >> (_scaleChromaMargin?scaleX:0);
00715     unsigned totalWidth   = scaledWidth + 2*xmargin;
00716     unsigned totalHeight  = scaledHeight +2*ymargin;
00717 
00718     if( _alignment )
00719     {
00720       // make sure buffer lines are align
00721       CHECK( _alignment != MEMORY_ALIGN_DEF_SIZE, "Unsupported alignment" );
00722       totalWidth = ( ( totalWidth + _alignment - 1 ) / _alignment ) * _alignment;
00723     }
00724     uint32_t area = totalWidth * totalHeight;
00725     CHECK( !area, "Trying to create a buffer with zero area" );
00726 
00727     m_origin[i] = ( Pel* ) xMalloc( Pel, area );
00728     Pel* topLeft = m_origin[i] + totalWidth * ymargin + xmargin;
00729     bufs.push_back( PelBuf( topLeft, totalWidth, _area.width >> scaleX, _area.height >> scaleY ) );
00730   }
00731 }
00732 
00733 void PelStorage::createFromBuf( PelUnitBuf buf )
00734 {
00735   chromaFormat = buf.chromaFormat;
00736 
00737   const uint32_t numCh = vtm::getNumberValidComponents( chromaFormat );
00738 
00739   bufs.resize(numCh);
00740 
00741   for( uint32_t i = 0; i < numCh; i++ )
00742   {
00743     PelBuf cPelBuf = buf.get( ComponentID( i ) );
00744     bufs[i] = PelBuf( cPelBuf.bufAt( 0, 0 ), cPelBuf.stride, cPelBuf.width, cPelBuf.height );
00745   }
00746 }
00747 
00748 void PelStorage::swap( PelStorage& other )
00749 {
00750   const uint32_t numCh = vtm::getNumberValidComponents( chromaFormat );
00751 
00752   for( uint32_t i = 0; i < numCh; i++ )
00753   {
00754     // check this otherwise it would turn out to get very weird
00755     CHECK( chromaFormat                   != other.chromaFormat                  , "Incompatible formats" );
00756     CHECK( get( ComponentID( i ) )        != other.get( ComponentID( i ) )       , "Incompatible formats" );
00757     CHECK( get( ComponentID( i ) ).stride != other.get( ComponentID( i ) ).stride, "Incompatible formats" );
00758 
00759     std::swap( bufs[i].buf,    other.bufs[i].buf );
00760     std::swap( bufs[i].stride, other.bufs[i].stride );
00761     std::swap( m_origin[i],    other.m_origin[i] );
00762   }
00763 }
00764 
00765 void PelStorage::destroy()
00766 {
00767   chromaFormat = NUM_CHROMA_FORMAT;
00768   for( uint32_t i = 0; i < MAX_NUM_COMPONENT; i++ )
00769   {
00770     if( m_origin[i] )
00771     {
00772       xFree( m_origin[i] );
00773       m_origin[i] = nullptr;
00774     }
00775   }
00776   bufs.clear();
00777 }
