00813 
00814 template<>
00815 void UnitBuf<Pel>::colorSpaceConvert(const UnitBuf<Pel> &other, const bool forward, const ClpRng& clpRng)
00816 {
00817   const Pel* pOrg0 = bufs[COMPONENT_Y].buf;
00818   const Pel* pOrg1 = bufs[COMPONENT_Cb].buf;
00819   const Pel* pOrg2 = bufs[COMPONENT_Cr].buf;
00820   const int  strideOrg = bufs[COMPONENT_Y].stride;
00821 
00822   Pel* pDst0 = other.bufs[COMPONENT_Y].buf;
00823   Pel* pDst1 = other.bufs[COMPONENT_Cb].buf;
00824   Pel* pDst2 = other.bufs[COMPONENT_Cr].buf;
00825   const int strideDst = other.bufs[COMPONENT_Y].stride;
00826 
00827   int width = bufs[COMPONENT_Y].width;
00828   int height = bufs[COMPONENT_Y].height;
00829   int maxAbsclipBD = (1 << (clpRng.bd + 1)) - 1;
00830   int r, g, b;
00831   int y0, cg, co;
00832 
00833   CHECK(bufs[COMPONENT_Y].stride != bufs[COMPONENT_Cb].stride || bufs[COMPONENT_Y].stride != bufs[COMPONENT_Cr].stride, "unequal stride for 444 content");
00834   CHECK(other.bufs[COMPONENT_Y].stride != other.bufs[COMPONENT_Cb].stride || other.bufs[COMPONENT_Y].stride != other.bufs[COMPONENT_Cr].stride, "unequal stride for 444 content");
00835   CHECK(bufs[COMPONENT_Y].width != other.bufs[COMPONENT_Y].width || bufs[COMPONENT_Y].height != other.bufs[COMPONENT_Y].height, "unequal block size")
00836 
00837     if (forward)
00838     {
00839       for (int y = 0; y < height; y++)
00840       {
00841         for (int x = 0; x < width; x++)
00842         {
00843           r = pOrg2[x];
00844           g = pOrg0[x];
00845           b = pOrg1[x];
00846 
00847           co = r - b;
00848           int t = b + (co >> 1);
00849           cg = g - t;
00850           pDst0[x] = t + (cg >> 1);
00851           pDst1[x] = cg;
00852           pDst2[x] = co;
00853         }
00854         pOrg0 += strideOrg;
00855         pOrg1 += strideOrg;
00856         pOrg2 += strideOrg;
00857         pDst0 += strideDst;
00858         pDst1 += strideDst;
00859         pDst2 += strideDst;
00860       }
00861     }
00862     else
00863     {
00864       for (int y = 0; y < height; y++)
00865       {
00866         for (int x = 0; x < width; x++)
00867         {
00868           y0 = pOrg0[x];
00869           cg = pOrg1[x];
00870           co = pOrg2[x];
00871 
00872           y0 = Clip3((-maxAbsclipBD - 1), maxAbsclipBD, y0);
00873           cg = Clip3((-maxAbsclipBD - 1), maxAbsclipBD, cg);
00874           co = Clip3((-maxAbsclipBD - 1), maxAbsclipBD, co);
00875 
00876           int t = y0 - (cg >> 1);
00877           pDst0[x] = cg + t;
00878           pDst1[x] = t - (co >> 1);
00879           pDst2[x] = co + pDst1[x];
00880         }
00881 
00882         pOrg0 += strideOrg;
00883         pOrg1 += strideOrg;
00884         pOrg2 += strideOrg;
00885         pDst0 += strideDst;
00886         pDst1 += strideDst;
00887         pDst2 += strideDst;
00888       }
00889     }
00890 }
